import{_ as s,l as i,o as a,c,v as r,p as l,x as o,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"内存屏障","description":"","frontmatter":{"title":"内存屏障","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-barrier-os.md","filePath":"cs/memory-barrier-os.md","lastUpdated":1789023840000}'),m={name:"cs/memory-barrier-os.md"};function h(_,e,u,f,E,A){const t=i("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="内存屏障" tabindex="-1">内存屏障 <a class="header-anchor" href="#内存屏障" aria-label="Permalink to &quot;内存屏障&quot;">​</a></h1><div class="epigraph"><p>临界区括号若只是源码里相邻的两行，编译器与 CPU 都可以把共享访存挪出括号；屏障把它钉回程序员以为的顺序。</p><footer>—— 据 Love, Linux Kernel Development；Lamport 顺序一致性与内核文档对 barrier 的整理</footer></div><p><a href="/cs/race-critical">上一课</a>要求共享不变量只在临界区里改，但还没说机器是否按源码序提交那些访存。<a href="/cs/memory-consistency">存储一致性</a> 在体系课给出 SC 与放宽模型。缺口是操作系统用法：<strong>内存屏障</strong>——防止编译器重排，并在弱序 CPU 上插入 fence，使「解锁前的写」被他核在「看到锁已释放」之前看见。本课不重导 TSO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无锁标志 <code>ready=1</code> 若排到 <code>data</code> 的写之前，读者看见 ready 仍可能读到旧 data。关中断不发射到别的核。缺口不是再定义竞争，而是承认：互斥锁的获取/释放必须带 <strong>acquire/release</strong> 语义，单独的 <code>LOAD</code>/<code>STORE</code> 要在文档化的点插 <code>smp_mb</code> 一类。内核把这写成显式屏障，而不是假设 SC。</p><p><span class="marginnote">编译器屏障挡住代码运动；CPU fence 挡住 store/load 在总线上的可见序。两者都要，对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写者：更新数据，然后 <code>store-release</code> 标志。读者：<code>load-acquire</code> 标志，然后读数据。锁实现把 acquire 放在拿到锁之后、临界区之前，release 放在写完临界区之后、清锁字之前。本课不把每架构的指令助记符列完。</p>',8)),(a(),l(p,null,{default:o(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20REL%5B%22release%20%E6%A0%87%E5%BF%97%22%5D%0A%20%20ACQ%5B%22acquire%20%E8%AF%BB%E6%A0%87%E5%BF%97%22%5D%20--%3E%20R%5B%22%E8%AF%BB%E6%95%B0%E6%8D%AE%22%5D%0A%20%20REL%20--%3E%20ACQ%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与<a href="/cs/percpu">per-CPU</a> 的关系：本核独享的槽若从未被他核读，可少加屏障；一旦跨核，纪律回来。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>屏障让临界区在多核上「看起来像原子」成为可实现的：他核要么看不见区内中间态，要么还看不见锁已释放。没有它，上一课的交错论证只对顺序一致纸机器成立。设备 DMA 与内存之间还有另一道，属 I/O 课；本课对象是 CPU 之间。</p><p>过度屏障会毁掉流水线；内核习惯用最弱足够的 acquire/release，而不是每处全序 fence。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 内存模型的全部 memory_order 枚举当 OS 正文，不写用户态如何探测乱序。也不把 RCU 的 synchronize 提前请进来。原子读改写指令本身既改数据又常自带屏障，下一课。</p><p>后课默认：跨核可见序要屏障或等价的锁语义。把「读改写」收成一条不可切的指令，下一课讲原子 RMW。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>临界区需要 acquire/release；源码相邻不等于可见序。</li><li>编译器屏障与 CPU fence 分工。</li><li>原子读改写是下一课。</li><li>出处：Love, <em>LKD</em>；体系课 <a href="/cs/memory-consistency">存储一致性</a>。</li></ul>',9))])}const C=s(m,[["render",h]]);export{q as __pageData,C as default};
